<?php
namespace App\Commands;
use App\Libraries\AuditLogService;use App\Models\UserModel;use CodeIgniter\CLI\BaseCommand;use CodeIgniter\CLI\CLI;
class PromotePlatformAdmin extends BaseCommand { protected $group='Mailora';protected $name='mailora:promote-admin';protected $description='Promote a user to platform admin.';protected $usage='mailora:promote-admin <email>';public function run(array $params):void{$email=$params[0]??null;if(!$email||!filter_var($email,FILTER_VALIDATE_EMAIL)){CLI::error('Provide a valid email.');return;}$m=new UserModel();$u=$m->where('email',strtolower($email))->first();if(!$u){CLI::error('User not found.');return;}$m->update($u['id'],['account_level'=>1,'account_type'=>'platform_admin','user_type'=>'platform_admin','parent_user_id'=>null,'reseller_id'=>null,'session_version'=>(int)$u['session_version']+1]);(new AuditLogService())->record('user.promoted_platform_admin',$u,[],'user',$u['uuid']);CLI::write("{$email} is now a platform admin.",'green');} }
